create table if not exists categories (id bigint generated by default as identity primary key, name text not null unique, slug text not null unique, description text, created_at timestamptz not null default now());
create table if not exists products (id bigint generated by default as identity primary key, name text not null, slug text not null unique, description text, category_id bigint references categories(id) on delete set null, price numeric(10,2) not null check (price >= 0), sale_price numeric(10,2) check (sale_price >= 0), sku text unique, sizes jsonb not null default '[]'::jsonb, stock integer not null default 0 check (stock >= 0), image_url text, status text not null default 'active' check (status in ('draft','active','archived')), featured boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists product_images (id bigint generated by default as identity primary key, product_id bigint not null references products(id) on delete cascade, url text not null, sort_order integer not null default 0);
create table if not exists orders (id bigint generated by default as identity primary key, customer_name text not null, phone text not null, email text, address text not null, city text not null, state text not null, pincode text not null, landmark text, subtotal numeric(10,2) not null check (subtotal >= 0), total numeric(10,2) not null check (total >= 0), payment_status text not null default 'not_applicable' check (payment_status in ('not_applicable','pending')), status text not null default 'pending' check (status in ('pending','confirmed','processing','shipped','delivered','cancelled')), created_at timestamptz not null default now());
create table if not exists order_items (id bigint generated by default as identity primary key, order_id bigint not null references orders(id) on delete cascade, product_id bigint not null references products(id), product_name text not null, size text, quantity integer not null check (quantity > 0), unit_price numeric(10,2) not null check (unit_price >= 0));
create table if not exists order_status_history (id bigint generated by default as identity primary key, order_id bigint not null references orders(id) on delete cascade, status text not null, note text, created_at timestamptz not null default now());
create index if not exists products_status_idx on products(status);
create index if not exists order_items_order_idx on order_items(order_id);
create index if not exists order_history_order_idx on order_status_history(order_id);

